sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var P = 'x_2056099_indust_0_';
    var grProd = new GlideRecord(P + 'mat_master');
    grProd.addActiveQuery();
    grProd.addNotNullQuery('standard_cost');
    grProd.addNotNullQuery('unit_of_measure');
    grProd.setLimit(1);
    grProd.query();
    if (!grProd.next()) { stepResult.setOutputMessage('FAIL: No active product with cost+UOM'); return false; }
    var prodSysId = grProd.getUniqueValue();
    var prodName = grProd.getValue('name');
    var unitPrice = parseFloat(grProd.getValue('standard_cost'));
    var uom = grProd.getValue('unit_of_measure');
    assertEqual({ name: 'Product name displayed', shouldbe: true, value: prodName.length > 0 });
    assertEqual({ name: 'Unit price displayed', shouldbe: true, value: unitPrice > 0 });
    assertEqual({ name: 'UOM displayed', shouldbe: true, value: uom.length > 0 });
    var quantity = 5;
    assertEqual({ name: 'Positive quantity', shouldbe: true, value: quantity > 0 });
    var lineTotal = quantity * unitPrice;
    assertEqual({ name: 'Line total correct', shouldbe: quantity * unitPrice, value: lineTotal });
    var cartItem = { product_sys_id: prodSysId, quantity: quantity, uom: uom, line_total: lineTotal };
    assertEqual({ name: 'Cart has selected product', shouldbe: prodSysId, value: cartItem.product_sys_id });
    assertEqual({ name: 'Cart has correct quantity', shouldbe: quantity, value: cartItem.quantity });
    assertEqual({ name: 'Cart line total matches', shouldbe: lineTotal, value: cartItem.line_total });
    assertEqual({ name: 'UOM preserved in cart', shouldbe: uom, value: cartItem.uom });
    stepResult.setOutputMessage('Cart: Product=' + prodName + ' Qty=' + quantity + ' Total=' + lineTotal);
    return true;
})(outputs, steps, params, stepResult, assertEqual);
